import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────
  // 1. GEOMETRY & MATERIAL
  // ─────────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Load texture and apply to material
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.colorNode = new THREE.TextureNode(texture, uv());
    material.needsUpdate = true;
  });

  const mesh = new THREE.Mesh(geometry, material);
  const group = new THREE.Group();
  group.add(mesh);

  // ─────────────────────────────────────────────────────────────────
  // 2. SCENE PLACEMENT
  // ─────────────────────────────────────────────────────────────────
  const pos = config.scenePosition || { x: 1.25, y: 1.6, z: 0 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // ─────────────────────────────────────────────────────────────────
  // 3. CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────────
  const primitiveCleanups = [];

  // Apply parallax-scroll
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive.name === 'parallax-scroll') {
        const result = ctx.primitives['parallax-scroll'](group, primitive.params || {});
        if (result && result.cleanup) {
          primitiveCleanups.push(result.cleanup);
        }
      }
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // 4. INTERACTION HANDLERS
  // ─────────────────────────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;

  const onHover = () => {
    if (pressTimeline) pressTimeline.kill();
    if (hoverTimeline) hoverTimeline.kill();

    // Subtle rise-in: 0.15 units, power3.out, 0.7s
    hoverTimeline = gsap.to(group.position, {
      y: pos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: pos.y,
      duration: 0.6,
      ease: 'power2.out',
    });
  };

  const onClick = () => {
    if (pressTimeline) pressTimeline.kill();

    // Press-down: scale 0.97, 120ms, back.out
    pressTimeline = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          duration: 0.3,
          ease: 'power2.out',
        });
      },
    });

    // Emit navigation event
    ctx.emit('hub-pricing.select', {});
  };

  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
  };

  // ─────────────────────────────────────────────────────────────────
  // 5. CLEANUP
  // ─────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    for (const cleanup of primitiveCleanups) {
      cleanup();
    }
    geometry.dispose();
    material.dispose();
  };

  return group;
}
